"""Presentation-only layouts; numerical evidence stays in build_deck.py notes."""
def kid(happy=False):
 return '<div class="kid-scene"><div class="orbit o1">missing history</div><div class="orbit o2">restarts</div><div class="orbit o3">customer demand</div><div class="kid '+('happy' if happy else '')+'"><div class="tuft"></div><div class="eyes"><i></i><i></i></div><div class="mouth"></div><div class="patch">+</div><div class="shirt">SOL</div><div class="feet"></div></div><div class="kid-caption">'+('Ready for the next priority.' if happy else 'Lower priority for six months.')+'</div></div>'
def panel(label,big,copy,cls=''):
 return f'<div class="visual-panel {cls}"><div class="eyebrow">{label}</div><div class="display-number">{big}</div><p>{copy}</p></div>'
def bar(label,width,value,cls=''):
 return f'<div class="bar-row"><div class="bar-label">{label}</div><div class="bar-track"><div class="bar-fill {cls}" style="width:{width}%"></div></div><strong>{value}</strong></div>'
def apply(slides):
 s=slides[0];s['title']='Solana: time to<br><span class="green">revisit the priority.</span>'
 s['body']='<div class="hero-split"><div><p class="hero-copy">Our dev team already owns Solana.<br>We kept it at lower priority for six months.</p><div class="pill">Three paths to reliable customer data</div><p class="subtle">Cambrian · 12 October 2026</p></div>'+kid()+'</div>'
 s['takeaway']='Customer demand now calls for a priority decision and dedicated dev-team capacity.'
 s['notes']+=' User clarification: the existing dev team is already responsible for Solana. Keeping it in the background at lower priority for the last six months was a deliberate prioritization decision. This deck proposes revisiting that priority and allocating capacity; it does not propose assigning a new owner.'
 s=slides[1];s['title']='Customer demand brings Solana<br>back into focus.'
 s['body']='<div class="journey"><div><span>01</span><h3>Positions</h3><p>What did I own?<br>When did it change?</p></div><b>→</b><div><span>02</span><h3>Fees</h3><p>What did I earn?<br>Can I reconcile it?</p></div><b>→</b><div><span>03</span><h3>History</h3><p><strong>2024 required</strong><br>2023 is a later option.</p></div></div><div class="callout">Lhava needs the actions inside each transaction, including nested LP strategy calls.</div>'
 s=slides[2];s['title']='Lower priority left these issues<br>for the next investment.'
 s['body']='<div class="debt-loop"><div class="loop-center"><strong>$2k</strong><small>/ month at Pinax</small><span>2 servers · Base + Solana</span></div><div class="loop-item"><b>01 · Old hardware</b><p>Restarts → repeated work</p></div><div class="loop-item"><b>02 · Missing instructions</b><p>Incomplete history → investigation</p></div><div class="loop-item"><b>03 · Storage limits</b><p>Expiry rules → lost history</p></div><div class="loop-item"><b>04 · Export friction</b><p>Moving data → vendor dependency</p></div></div>'
 s['takeaway']='The existing dev team needs allocated time to address these reliability and history gaps.'
 s['notes']+=' The user reports six months of deliberately lower priority. These issues are the current work backlog; the deck does not establish when each issue arose or attribute every issue to that decision.'
 s=slides[3];s['title']='We made room by letting history disappear.'
 s['body']='<div class="storage-label"><strong>15.36 TB</strong><span>shared disk, measured</span></div><div class="disk-stack"><div style="width:32.32%">Solana<br><b>4.96 TB</b></div><div style="width:20.12%">Other used<br><b>3.09 TB</b></div><div style="width:47.56%">Free today<br><b>7.31 TB</b></div></div><div class="visual-grid">'+panel('WITHIN SOLANA','2.53 TB','Tables that expire rows after one month.','warm')+panel('WITHIN SOLANA','1.32 TB','Raw token balances with short retention.')+panel('WITHIN SOLANA','0.134 TB','Retained Meteora DLMM data.')+'</div>'
 s['notes']+=' Disk chart: “Other used” is filesystem used minus active Solana parts, about 3.09 TB. It includes all other database data plus system/inactive/filesystem use; it is not an independently measured database group. Percentages are shares of total disk, not shares of Solana.'
 s=slides[4];s['title']='Give it the right-sized room.'
 s['body']='<div class="visual-grid two">'+panel('CUSTOMER DATASET · MODELED','0.56 TB','Meteora positions + fees since 2024.<br><b>0.87 TB</b> after another year.','featured')+panel('RAW BALANCES · SCENARIO','~40 TB','Every balance change since 2024.<br><b>~55 TB</b> if we add 2023.','warm')+'</div><div class="history-strip"><span>2023<br><small>Optional; Meteora size unmeasured</small></span><span>2024 → today<br><small>Customer’s required history</small></span><span>Next 12 months<br><small>Keep collecting, keep retaining</small></span></div><p class="subtle">Different datasets, different fidelity. Raw balances assume a constant recent daily rate. Full raw blocks remain unsized.</p>'
 s=slides[5];s['title']='Three paths for the next investment.'
 s['body']='<div class="visual-grid options">'+panel('PATH 1','Repair','<h3>Stay with Pinax</h3>Improve servers. Rebuild from 2023.<hr>Vendor dependency continues.')+panel('PATH 2 · PREFERRED IF VALIDATED','Bridge','<h3>Recover, then own</h3>Backfill 2024. Export. Move future collection.<hr>More work; better control.','featured')+panel('PATH 3','Start','<h3>Own from now</h3>Build on onstream immediately.<hr>2024 coverage remains unresolved.')+'</div>'
 for i,t in [(6,'Path 1 · Improve the current setup.'),(7,'Path 2 · Recover its past. Own its future.'),(8,'Path 3 · Build live capture. History still waits.')]:slides[i]['title']=t
 s=slides[7];s['body']='<div class="bridge"><div class="lane"><span class="lane-label">RECOVER THE PAST</span><div>Pinax<small>sample 2024 first</small></div><b>→</b><div>GCP archive<small>export + restore test</small></div></div><div class="lane"><span class="lane-label">PROTECT THE FUTURE</span><div>Solana network<small>new blocks</small></div><b>→</b><div>OVH + onstream<small>capture + retain</small></div></div><div class="bridge-target"><strong>↓</strong><div>One validated dataset → Customer API</div><small>Proposed serving: ClickHouse + API on OVH</small></div></div><div class="pill">Exit only after quality, restore, live stability and Base continuity pass.</div>'
 s=slides[8];s['body']='<div class="coverage-line"><div class="past"><h3>2024 → now</h3><p>Historical gap remains.<br>Preserve useful existing data.</p><span>? ? ? ? ?</span></div><div class="start-marker">START<br>HERE</div><div class="future"><h3>Now → future</h3><p>Our collection. Our retention.<br>Our maintenance responsibility.</p><span>● ━ ● ━ ● ━ ●</span></div></div><div class="callout">Onstream can replay available history. It cannot recreate instructions a source discarded.</div>'
 s=slides[9];s['title']='Every path needs data unification.'
 s=slides[10];s['title']='A real operating budget for a real product.'
 s['body']='<div class="visual-grid two">'+panel('PATH 1 · CURRENT BILL','$2,000','Per month for the Pinax bundle.<br><b>+ server/storage upgrade quote</b>')+panel('PATHS 2 / 3 · PLANNING ALLOWANCE','$2,700–5,500','Per month for our Solana platform.<br><b>+ Base replacement + archive + transfer</b>','featured')+'</div><div class="cost-parts"><span>Node<br><b>$1.5–3k</b></span><span>Database + API<br><b>$1–2k</b></span><span>Monitoring + backup<br><b>$0.2–0.5k</b></span></div><p class="subtle">Selected 0.56 TB GCP archive ≈ $10/month. Pinax overlap adds $2k/month until exit.<br>Allowances exclude labor, extra HA replicas, raw-block archive, source fees, setup and tax adjustments.</p>'
 s=slides[11];s['title']='Allocate dev-team time to the chosen path.'
 s['body']='<div class="effort-chart">'+bar('1 · Pinax',20/30.5*100,'20 days')+bar('2 · Bridge, then own',100,'30.5 days','highlight')+bar('3 · Own from now',25/30.5*100,'25 days')+'</div><div class="visual-grid">'+panel('PLANNING RANGES','15–27.5 / 20–42.5 / 17.5–35','Engineer-days, paths 1 / 2 / 3.','compact')+panel('ADD POOL STATE + FEES','+14 days','Adjusted estimate; range 8.5–19.','compact')+panel('ONGOING ONSTREAM CARE','1–2.5 days/mo','Assumed maintenance reserve.','compact')+'</div>'
 s=slides[12];s['title']='About 32 days to recover the 2024 backlog.'
 s['body']='<div class="replay-top"><strong>~32</strong><span>historical days per day<br>user-reported replay rate</span></div><div class="visual-grid two">'+panel('2024 → 11 OCT 2026','~31.7 days','1,015 historical days ÷ 32.<br>About 32 days of continuous replay.','featured')+panel('INCLUDING 2023','~43.1 days','Another 365 historical days adds ~11.4 days.<br>1,380 historical days ÷ 32.')+'</div><p class="subtle">Replay only: assumes the reported rate is sustained and history is available.<br>If 32× also includes live ingestion, catching up the 2024 backlog takes ~32.7 days.<br>Engineering, transfer, validation and interruptions require separate allowances.</p>'
 s=slides[13];s['title']='Three gates before we leave Pinax.'
 s['body']='<div class="journey gates"><div><span>01</span><h3>History</h3><p>2024 source passes.<br>Missing fields are explicit.</p></div><b>→</b><div><span>02</span><h3>Portability</h3><p>Export agreed.<br>Restore works. Base has a plan.</p></div><b>→</b><div><span>03</span><h3>Readiness</h3><p>Restarts and upgrades tested.<br>Customer accepts output.</p></div></div><div class="callout">If history fails, Path 3 needs customer acceptance of a shorter history.</div>'
 s=slides[14];s['title']='Agree the priority. Allocate team capacity.'
 s['body']='<div class="hero-split closing"><div><div class="action-line"><b>Data</b><span>Prove the 2024 history.</span></div><div class="action-line"><b>Platform</b><span>Validate onstream; reserve maintenance time.</span></div><div class="action-line"><b>Operations</b><span>Secure export terms + Base continuity.</span></div><div class="action-line"><b>Product</b><span>Agree the output with Lhava.</span></div><div class="pill">First checkpoint: 5 working days / 2.5–4 engineer-days</div></div>'+kid(True)+'</div>'
 s['takeaway']='Give the existing dev team time and budget for the pilot. Then choose with evidence.'
